DEFINITIONS=[{'symbol': '600136', 'primary': '1225021044', 'pages': [1, 2], 'question': '调查已结案、报表已重述，为什么仍是ST？', 'risk_group': '历史虚假记载处罚与撤销时间条件', 'known_at_anchor': '3月20日收到正式处罚决定后继续其他风险警示，公司称相关年度报表已追溯重述；2025财报无保留意见。结案、重述和财报意见不替代处罚门槛及正式撤销。', 'watch': '分别核决定作出原件、满12个月条件及正式撤销，不将3月20日收到日当作出日或自动摘帽日。', 'supporting': [{'id': '1225021033', 'pages': [1], 'note': '处罚结案与个人、公司主体分别核。'}, {'id': '1225145292', 'pages': [2], 'note': '扫描原页无保留意见，不豁免处罚相关其他风险警示。'}]}, {'symbol': '600165', 'primary': '1224930399', 'pages': [1, 2, 3], 'question': '重整已执行、退市警示已撤，剩下的ST是什么？', 'risk_group': '重整一项已正式撤销，其他警示及经营另核', 'known_at_anchor': '1月12日获准撤销因重整触发的退市风险警示，1月14日生效，其他风险警示保留。4月董事会专项披露旧持续经营审计事项已消除，2025审计另有专利诉讼强调事项；不把旧持续经营段原样当最新，也不把新强调事项当保留意见或自动ST原因。', 'watch': '逐项核旧停产、持续经营与处罚相关条件及正式撤销；重整执行完毕、旧审计事项消除和全部摘帽分开，专利诉讼与真实经营另核。', 'supporting': [{'id': '1224914772', 'pages': [1, 2, 3], 'note': '2025年末法院裁定计划执行完毕，公告后续批准另由1月正式节点认证。'}, {'id': '1225172319', 'pages': [1, 2], 'note': '扫描董事会专项：旧持续经营事项消除，不能当全部其他警示已撤。'}, {'id': '1225172303', 'pages': [2], 'note': '2025财报带专利诉讼强调事项的无保留意见。'}, {'id': '1225401321', 'pages': [10, 12], 'note': '7月1日回复继续说明旧持续事项消除与新专利风险，未认证诉讼胜诉。'}]}, {'symbol': '600169', 'primary': '1224781398', 'pages': [1, 2], 'question': '公司称旧项目风险已出清，为什么还要核处罚门槛？', 'risk_group': '财务虚假记载处罚相关其他风险警示', 'known_at_anchor': '2025年11月4日起因年度财务虚假记载实施ST；之后已披露收到正式处罚决定。2025财报无保留，不等于处罚门槛或正式撤销已完成。原公告称项目已完工、资产已剥离，是公司经营影响说明。', 'watch': '核处罚决定作出日、重述完成与撤销条件及正式生效；近日收到不猜精确收到日，不将项目风险出清声明外推全部警示解除。', 'supporting': [{'id': '1224901278', 'pages': [1], 'note': '公司披露近日收到决定，不能从披露日推精确收到或作出日。'}, {'id': '1225132800', 'pages': [2], 'note': '2025财报无保留，关键审计事项另列，不当保留意见。'}]}, {'symbol': '600180', 'primary': '1225251103', 'pages': [1, 2], 'question': '为何同时有退市风险和其他风险警示？', 'risk_group': '财报无法表示与内控否定叠加', 'known_at_anchor': '4月30日起财报无法表示意见触发退市风险警示，内控否定另叠加其他风险警示。6月披露拟先行庭外重组，成熟后再申请预重整或重整；自主协商不具司法强制效力，不能当法院受理或重整完成。', 'watch': '分别核审计证据缺口、内控整改、真实催收和正式司法硬节点；债权抵销不当现金到账，定期进展和异常波动公告不当多次独立验证。', 'supporting': [{'id': '1225251063', 'pages': [2, 3, 4], 'note': '扫描原页无法表示意见基础含回款/减值、联营资料、或有事项与持续经营，不只看利润。'}, {'id': '1225387913', 'pages': [1, 2], 'note': '6月庭外重组尚属拟议，财务与司法程序分别核。'}]}]
